package stream

import (
	"fmt"
	"strconv"
	"strings"
)

// The master playlist composer (pack-manifest-audio D1): the build root's
// index.m3u8 is rendered by the lane from the variant layout plus the probed
// head-playlist facts — never ffmpeg's generated master, which double-lists
// every rendition as an EXT-X-STREAM-INF variant (finding A: hls.js picks the
// video-only variant and never requests any audio rendition). The composed
// master declares ONE video variant and the audio renditions ONLY as
// EXT-X-MEDIA:TYPE=AUDIO members of one group, with unique NAMEs (the stream's
// language fact else a stable "Audio K" ordinal), LANGUAGE when known, and
// exactly one DEFAULT=YES — the embedded audio, the pack's primary track and
// the sole default (settled at GATE 1; language-based defaulting declined) —
// the voiceovers riding AUTOSELECT=YES,DEFAULT=NO. The composition is pure
// and strictly fail-open: absent probe facts drop the attribute (BANDWIDTH
// falls back to a conservative constant), an uncomposable codec record drops
// every CODECS attribute — the corrected SHAPE always publishes, never a
// failed pack, and identical facts yield byte-identical bytes. The
// single-variant degenerate master (one variant whose CODECS names the video
// and the muxed audio, no EXT-X-MEDIA group, no AUDIO attribute) rides the
// same composer: the build root holds only the master on every fresh pack
// (D3).

// fallbackBandwidth is the conservative BANDWIDTH fallback when the probed
// head playlist reports no video bit_rate. An understated BANDWIDTH costs a
// player nothing on this lane's builds — there is no lower variant to prefer
// instead — while an overstated one can make a strict player refuse.
const fallbackBandwidth = 2_000_000

// audioGroup is the EXT-X-MEDIA group id the rendition lane declares
// (renditionMap's agroup:aud) — the master's EXT-X-MEDIA entries and the
// variant line's AUDIO attribute must name exactly it.
const audioGroup = "aud"

// composeMaster renders a build's root master playlist: one EXT-X-STREAM-INF
// variant (vs[0], the video rendition) with BANDWIDTH (probed else
// fallbackBandwidth), RESOLUTION when probed, and CODECS when the record
// composed (the publish-time table — codecs non-nil implies every stream
// composed). On a rendition build the variant ties the audio group with
// AUDIO="aud" and one EXT-X-MEDIA entry follows per audio rendition (vs[1..],
// embedded first), URI pointing at its variant playlist; the single-variant
// degenerate (D3) muxes its audio into the variant — the CODECS value names
// video and audio together and no group exists. Pure.
func composeMaster(vs []variantPlaylist, variants [][]map[string]any, codecs []string) []byte {
	attrs := fmt.Sprintf("BANDWIDTH=%d", variantBandwidth(variants))
	if w, h := variantResolution(variants); w > 0 && h > 0 {
		attrs += fmt.Sprintf(",RESOLUTION=%dx%d", w, h)
	}
	if codecs != nil {
		if cs := muxedCodecs(variants[0]); cs != "" {
			attrs += fmt.Sprintf(",CODECS=%q", cs)
		}
	}
	if len(vs) > 1 { // rendition build: the variant ties the EXT-X-MEDIA group; a single-variant build muxes its audio
		attrs += fmt.Sprintf(",AUDIO=%q", audioGroup)
	}
	lines := []string{
		"#EXTM3U",
		"#EXT-X-STREAM-INF:" + attrs,
		vs[0].rel + "/index.m3u8",
	}
	seen := map[string]bool{}
	for k := 1; k < len(vs); k++ {
		lang := audioLanguage(variants[k])
		name := lang
		if name == "" || seen[name] {
			name = "Audio " + strconv.Itoa(k) // stable ordinal (rendK) — GROUP-ID NAMEs must be unique
		}
		seen[name] = true
		attrs := fmt.Sprintf("TYPE=AUDIO,GROUP-ID=%q,NAME=%q", audioGroup, name)
		if lang != "" {
			attrs += fmt.Sprintf(",LANGUAGE=%q", lang)
		}
		if k == 1 { // rend1: the embedded audio — the primary track, the sole default
			attrs += ",DEFAULT=YES,AUTOSELECT=YES"
		} else { // rendK+1: the voiceovers — selectable, never default
			attrs += ",DEFAULT=NO,AUTOSELECT=YES"
		}
		if codecs != nil {
			if cs := variantCodecs(variants[k], "audio"); cs != "" {
				attrs += fmt.Sprintf(",CODECS=%q", cs)
			}
		}
		attrs += fmt.Sprintf(",URI=%q", vs[k].rel+"/index.m3u8")
		lines = append(lines, "#EXT-X-MEDIA:"+attrs)
	}
	return []byte(strings.Join(lines, "\n") + "\n")
}

// variantBandwidth reads the first video stream's bit_rate off the probed
// variant facts (ffprobe reports it as a JSON string or number; "N/A" or an
// absent fact falls back). Pure.
func variantBandwidth(variants [][]map[string]any) int64 {
	if len(variants) == 0 {
		return fallbackBandwidth
	}
	for _, st := range variants[0] {
		if st["codec_type"] != "video" {
			continue
		}
		switch b := st["bit_rate"].(type) {
		case string:
			if n, err := strconv.ParseInt(strings.TrimSpace(b), 10, 64); err == nil && n > 0 {
				return n
			}
		case float64:
			if b > 0 {
				return int64(b)
			}
		}
		return fallbackBandwidth // the first video stream decides
	}
	return fallbackBandwidth
}

// variantResolution reads the first video stream's width and height off the
// probed variant facts (0,0 when absent — the attribute is then dropped).
// Pure.
func variantResolution(variants [][]map[string]any) (w, h int) {
	if len(variants) == 0 {
		return 0, 0
	}
	for _, st := range variants[0] {
		if st["codec_type"] != "video" {
			continue
		}
		wf, _ := st["width"].(float64)
		hf, _ := st["height"].(float64)
		return int(wf), int(hf)
	}
	return 0, 0
}

// audioLanguage reads the first audio stream's language tag off the probed
// variant facts ("" when absent or "und" — ffprobe's undefined-stream
// spelling is not a language fact). Pure.
func audioLanguage(streams []map[string]any) string {
	for _, st := range streams {
		if st["codec_type"] != "audio" {
			continue
		}
		tags, _ := st["tags"].(map[string]any)
		lang, _ := tags["language"].(string)
		lang = strings.TrimSpace(lang)
		if lang == "" || lang == "und" {
			return ""
		}
		return lang
	}
	return ""
}

// variantCodecs joins the composed RFC 6381 strings of one variant's streams
// of the given kind, in stream order. Valid only over facts the record
// composed from (codecs non-nil implies every stream composed); a kind the
// variant carries none of joins to "". Pure.
func variantCodecs(streams []map[string]any, kind string) string {
	var out []string
	for _, st := range streams {
		if st["codec_type"] == kind {
			out = append(out, codecString(st))
		}
	}
	return strings.Join(out, ",")
}

// muxedCodecs composes one variant line's CODECS value: the variant's video
// codec strings joined with its audio codec strings — the single-variant
// master's muxed variant names both (`CODECS="<video>,<audio>"`), a
// rendition's video-only rend0 names the video alone (its audio codecs ride
// the EXT-X-MEDIA entries). Pure.
func muxedCodecs(streams []map[string]any) string {
	video := variantCodecs(streams, "video")
	audio := variantCodecs(streams, "audio")
	switch {
	case video == "":
		return audio
	case audio == "":
		return video
	default:
		return video + "," + audio
	}
}
